using NexusOps.Web.Models;using Npgsql;
namespace NexusOps.Web.Services;
public interface ILaborStore{IReadOnlyList<LaborEmployee> ListEmployees();IReadOnlyList<WorkOrderLaborEntry> List(Guid orderId);void Add(Guid orderId,CreateLaborInput input);}
public sealed class PostgresLaborStore(NpgsqlDataSource ds,Guid tenant):ILaborStore{public IReadOnlyList<LaborEmployee> ListEmployees(){using var c=ds.CreateCommand("select id,coalesce(full_name,concat(first_name,' ',last_name)) from employees where tenant_id=$1 order by 2");c.Parameters.AddWithValue(tenant);using var r=c.ExecuteReader();var x=new List<LaborEmployee>();while(r.Read())x.Add(new(r.GetGuid(0),r.GetString(1)));return x;}public IReadOnlyList<WorkOrderLaborEntry> List(Guid id){using var c=ds.CreateCommand("select employee_name,started_at,ended_at,hourly_rate,note from work_order_labor_entries where tenant_id=$1 and work_order_id=$2 order by started_at desc");c.Parameters.AddWithValue(tenant);c.Parameters.AddWithValue(id);using var r=c.ExecuteReader();var x=new List<WorkOrderLaborEntry>();while(r.Read())x.Add(new(r.GetString(0),r.GetFieldValue<DateTimeOffset>(1),r.GetFieldValue<DateTimeOffset>(2),r.GetDecimal(3),r.IsDBNull(4)?null:r.GetString(4)));return x;}public void Add(Guid id,CreateLaborInput i){if(i.EndedAt<=i.StartedAt)throw new ArgumentException("Završetak mora biti nakon početka rada.");using var c=ds.CreateCommand("insert into work_order_labor_entries(tenant_id,work_order_id,employee_id,employee_name,started_at,ended_at,hourly_rate,note) select $1,$2,e.id,coalesce(e.full_name,concat(e.first_name,' ',e.last_name)),$3,$4,$5,$6 from employees e where e.id=$7 and e.tenant_id=$1");c.Parameters.AddWithValue(tenant);c.Parameters.AddWithValue(id);c.Parameters.AddWithValue(i.StartedAt);c.Parameters.AddWithValue(i.EndedAt);c.Parameters.AddWithValue(i.HourlyRate);c.Parameters.AddWithValue((object?)i.Note??DBNull.Value);c.Parameters.AddWithValue(i.EmployeeId);if(c.ExecuteNonQuery()!=1)throw new ArgumentException("Zaposlenik nije pronađen.");}}
public sealed class InMemoryLaborStore:ILaborStore{readonly List<LaborEmployee> e=[new(Guid.NewGuid(),"Ana Kovač"),new(Guid.NewGuid(),"Luka Marić")];readonly Dictionary<Guid,List<WorkOrderLaborEntry>> x=[];public IReadOnlyList<LaborEmployee> ListEmployees()=>e;public IReadOnlyList<WorkOrderLaborEntry> List(Guid id)=>x.GetValueOrDefault(id)??[];public void Add(Guid id,CreateLaborInput i){if(i.EndedAt<=i.StartedAt)throw new ArgumentException("Završetak mora biti nakon početka rada.");var p=e.SingleOrDefault(z=>z.Id==i.EmployeeId)??throw new ArgumentException("Zaposlenik nije pronađen.");if(!x.ContainsKey(id))x[id]=[];x[id].Add(new(p.Name,i.StartedAt,i.EndedAt,i.HourlyRate,i.Note));}}
